/* Phase 20 browser runtime bridge: local-first repository API for the legacy app. */
(function (global) {
  'use strict';
  const KEYS = { savedTrips: 'cme-saved-trips-v1', latestSavedTrip: 'cme-saved-trip-v1', draft: 'cme-planner-draft-v1', versions: 'cme-trip-versions-v1' };
  const clone = value => value == null ? value : JSON.parse(JSON.stringify(value));
  const read = (key, fallback) => { try { const raw = CMEStorage.getItem(key); return raw == null ? fallback : JSON.parse(raw); } catch (_) { return fallback; } };
  const write = (key, value) => CMEStorage.setItem(key, JSON.stringify(value));
  const normalize = (record, kind) => {
    if (!record || typeof record !== 'object' || Array.isArray(record)) return null;
    const slots = Array.isArray(record.slots) ? record.slots : [];
    const days = Math.max(1, Math.min(30, Number(record.days) || slots.length || 1));
    const cleanSlots = slots.slice(0, days).map(s => ({ morning: String(s?.morning ?? ''), afternoon: String(s?.afternoon ?? ''), evening: String(s?.evening ?? '') }));
    while (cleanSlots.length < days) cleanSlots.push({ morning: '', afternoon: '', evening: '' });
    const locks = Array.isArray(record.dayLocks) ? record.dayLocks.slice(0, days).map(Boolean) : Array(days).fill(false);
    while (locks.length < days) locks.push(false);
    const validPin = p => typeof p === 'string' && /^\d+:(morning|afternoon|evening)$/.test(p) && Number(p.split(':')[0]) < days;
    return { ...record, schemaVersion: 4, city: String(record.city || 'Shanghai'), days, slots: cleanSlots, style: String(record.style || 'balanced'), dayLocks: locks, pinnedSlots: [...new Set((Array.isArray(record.pinnedSlots) ? record.pinnedSlots : []).filter(validPin))], savedAt: String(record.savedAt || record.updatedAt || new Date().toISOString()), kind };
  };
  const list = () => { const a = read(KEYS.savedTrips, []); if (Array.isArray(a) && a.length) return a.map(t => normalize(t, 'saved-trip')).filter(Boolean); const legacy = normalize(read(KEYS.latestSavedTrip, null), 'saved-trip'); return legacy ? [legacy] : []; };
  const versions = () => { const v = read(KEYS.versions, {}); return v && typeof v === 'object' && !Array.isArray(v) ? v : {}; };
  const api = Object.freeze({
    listSavedTrips: list,
    getSavedTrip(id) { return list().find(t => t.id === String(id)) || null; },
    saveTrip(record) { const n = normalize({ ...record, id: record?.id || `trip-${Date.now()}`, savedAt: record?.savedAt || new Date().toISOString() }, 'saved-trip'); if (!n) throw new TypeError('Invalid trip'); const trips = list().filter(t => t.id !== n.id); trips.unshift(n); write(KEYS.savedTrips, trips); write(KEYS.latestSavedTrip, n); return clone(n); },
    deleteTrip(id) { const trips = list().filter(t => t.id !== String(id)); write(KEYS.savedTrips, trips); if (trips[0]) write(KEYS.latestSavedTrip, trips[0]); else CMEStorage.removeItem(KEYS.latestSavedTrip); const v = versions(); delete v[String(id)]; write(KEYS.versions, v); return trips.length; },
    saveDraft(record) { const n = normalize({ ...record, savedAt: record?.savedAt || new Date().toISOString() }, 'draft'); if (!n) throw new TypeError('Invalid draft'); write(KEYS.draft, n); return clone(n); },
    getDraft() { return normalize(read(KEYS.draft, null), 'draft'); }, clearDraft() { CMEStorage.removeItem(KEYS.draft); },
    listVersions(id) { return clone(versions()[String(id)] || []); },
    saveVersion(id, record, metadata = {}) { if (!id) throw new TypeError('tripId required'); const n = normalize({ ...record, savedAt: record?.savedAt || new Date().toISOString() }, 'version'); if (!n) throw new TypeError('Invalid version'); const v = versions(), arr = v[String(id)] || []; const next = Math.max(0, ...arr.map(x => Number(x.version) || 0)) + 1; const item = { ...n, version: next, versionName: metadata.versionName || `Version ${next}` }; v[String(id)] = [item, ...arr].slice(0, 20); write(KEYS.versions, v); return clone(item); },
    storageKeys: KEYS
  });
  global.CMETripRepository = api;
})(window);
(function(){
function repo(){return window.CMETripRepository;}
window.getSavedTrips=function(){return repo().listSavedTrips();};
window.schedulePlannerAutosave=function(label='Edit itinerary'){if(autosaveTimer)clearTimeout(autosaveTimer);plannerAutosaveStatus('Saving draft…');autosaveTimer=setTimeout(()=>{try{repo().saveDraft(plannerDraftPayload(label));plannerAutosaveStatus('Draft saved · '+new Date().toLocaleTimeString());}catch(e){plannerAutosaveStatus('Autosave unavailable · storage error');}},350);};
window.restorePlannerDraft=function(){try{const draft=repo().getDraft();if(!draft||!Array.isArray(draft.slots)||!draft.slots.length)return;const latestSaved=repo().listSavedTrips()[0]?.savedAt||'';if(draft.savedAt&&latestSaved&&draft.savedAt<=latestSaved)return;if(!confirm('A recoverable draft from '+new Date(draft.savedAt).toLocaleString()+' was found. Restore it?'))return;document.getElementById('planner-city').value=draft.city||'Shanghai';document.getElementById('planner-days').value=String(draft.days||draft.slots.length);document.getElementById('planner-style').value=draft.style||'balanced';currentTripId=draft.currentTripId||null;plannerHistoryReset();currentDayLocks=Array.isArray(draft.dayLocks)?draft.dayLocks.slice():[];currentPinnedSlots=Array.isArray(draft.pinnedSlots)?draft.pinnedSlots.slice():[];renderEditableItinerary(draft.city||'Shanghai',draft.slots.length,draft.style||'balanced',draft.slots);plannerHistoryReset();plannerHistoryCommit('Recovered draft');const name=document.getElementById('planner-trip-name');if(name)name.value=draft.name||'';plannerAutosaveStatus('Draft recovered · local only');}catch(e){console.warn('Draft recovery failed',e);}};
window.getTripVersions=function(){const out={};repo().listSavedTrips().forEach(t=>{const list=repo().listVersions(t.id);if(list.length)out[t.id]=list;});return out;};
window.saveTripVersion=function(){if(!currentItineraryDays.length){alert('Generate or load a trip first.');return;}if(!currentTripId){saveItinerary();return;}const item=repo().saveVersion(currentTripId,plannerDraftPayload('Manual version'));updateTripVersionPanel();plannerAutosaveStatus('Version '+item.version+' saved · '+new Date().toLocaleTimeString());alert('Version '+item.version+' saved locally.');};
window.saveItinerary=function(){if(window.__cmeTripSaveInProgress)return;const feedback=document.getElementById('planner-save-feedback');const setFeedback=(message,kind='info')=>{if(feedback){feedback.textContent=message;feedback.dataset.state=kind;}};if(!currentItineraryDays.length||!currentItineraryDays.some(d=>['morning','afternoon','evening'].some(k=>String(d[k]||'').trim()))){setFeedback('Add at least one activity before saving.','error');return;}window.__cmeTripSaveInProgress=true;const buttons=[...document.querySelectorAll('button[onclick="saveItinerary()"]')];buttons.forEach(b=>{b.disabled=true;b.dataset.originalText=b.textContent;b.textContent='Saving…';});const city=document.getElementById('planner-city').value;const name=(document.getElementById('planner-trip-name')?.value||'').trim()||city+' trip · '+new Date().toLocaleDateString();const data={id:'trip-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),schemaVersion:4,name,city,days:currentItineraryDays.length,style:document.getElementById('planner-style').value,slots:currentItineraryDays.map(d=>({...d})),dayLocks:currentDayLocks.slice(),pinnedSlots:currentPinnedSlots.slice(),text:itineraryText(),savedAt:new Date().toISOString()};try{repo().saveTrip(data);currentTripId=data.id;repo().saveVersion(currentTripId,plannerDraftPayload('Initial saved version'),{versionName:'Version 1'});repo().saveDraft(plannerDraftPayload('Saved trip'));setFeedback('✓ Trip saved on this device. You can load it from your saved trips below.','success');renderSavedTripsList();updateTripVersionPanel();renderMyChina();}catch(e){console.error(e);setFeedback('Save failed. Your browser storage may be unavailable or full.','error');}finally{window.__cmeTripSaveInProgress=false;buttons.forEach(b=>{b.disabled=false;b.textContent=b.dataset.originalText||'Save as new trip';});}};
window.deleteSavedTrip=function(id){if(!confirm('Delete this saved trip from this device?'))return;repo().deleteTrip(id);renderSavedTripsList();renderMyChina();updateTripVersionPanel();};
window.clearSavedItinerary=function(){const trips=repo().listSavedTrips();if(trips.length&&!confirm('Delete all saved trips from this device?'))return;trips.forEach(t=>repo().deleteTrip(t.id));alert('Saved trips deleted from this device.');renderSavedTripsList();renderMyChina();updateTripVersionPanel();};
window.restoreTripVersion=function(index){const list=currentTripId?repo().listVersions(currentTripId):[];const v=list[index];if(!v||!confirm('Restore '+(v.versionName||'this version')+'? Current draft will be autosaved before restoring.'))return;repo().saveDraft(plannerDraftPayload('Before version restore'));document.getElementById('planner-city').value=v.city;document.getElementById('planner-days').value=String(v.days||v.slots.length);document.getElementById('planner-style').value=v.style||'balanced';currentDayLocks=Array.isArray(v.dayLocks)?v.dayLocks.slice():[];currentPinnedSlots=Array.isArray(v.pinnedSlots)?v.pinnedSlots.slice():[];renderEditableItinerary(v.city,v.slots.length,v.style||'balanced',v.slots);plannerHistoryCommit('Restore '+(v.versionName||'version'));plannerAutosaveStatus('Version restored · draft autosaved');};
})();
